package vn.edu.eaut.lab10.controller;
import java.io.*;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import vn.edu.eaut.lab10.model.User;import vn.edu.eaut.lab10.repository.UserRepository;
@WebServlet("/user/profile") public class ProfileController extends HttpServlet{private final UserRepository r=new UserRepository();protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{q.getRequestDispatcher("/user/profile.jsp").forward(q,p);}protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{User old=(User)q.getSession().getAttribute("currentUser");old.setFullName(q.getParameter("fullName"));old.setEmail(q.getParameter("email"));r.update(old);q.getSession().setAttribute("currentUser",old);q.setAttribute("success","Cập nhật hồ sơ thành công.");q.getRequestDispatcher("/user/profile.jsp").forward(q,p);}}